    private static let safetyScenarios = Exercise(
        title: "Sicherheit zu Hause und unterwegs",
        instructions: "Beschreiben Sie, wie Sie sich in der Situation richtig verhalten.",
        section: .functionalSkills,
        type: .openEnded,
        trackedType: nil,
        difficulty: .medium,
        groupKey: "safetyScenarios",
        isHeldForReview: true,
        items: [
            ExerciseItem(id: UUID(), prompt: "Sie kochen, und plötzlich steigt dichter Rauch aus dem Backofen. Die Küche brennt. Was tun Sie?", options: [], correctAnswer: "Ich verlasse die Wohnung sofort, schließe die Tür hinter mir und rufe von draußen die 112 an. Ich nenne meinen Namen, die Adresse und sage, dass es brennt.", explanation: "Rauch ist gefährlicher als das Feuer selbst. Die 112 erreicht die Feuerwehr, und die Einsatzkräfte brauchen vor allem die genaue Adresse."),
            ExerciseItem(id: UUID(), prompt: "In Ihrem Treppenhaus riecht es stark nach Gas. Wie verhalten Sie sich?", options: [], correctAnswer: "Ich mache kein Licht an und betätige keinen Schalter. Ich öffne wenn möglich die Fenster, verlasse das Haus und rufe von draußen die 112 an.", explanation: "Ein Funke von einem Schalter oder einer Klingel kann Gas entzünden. Darum geht man ohne elektrische Geräte hinaus und ruft erst im Freien an."),
            ExerciseItem(id: UUID(), prompt: "Es klingelt, ein Mann sagt, er komme von den Stadtwerken und müsse sofort die Wohnung prüfen. Sie haben keinen Besuch erwartet. Was tun Sie?", options: [], correctAnswer: "Ich öffne die Tür nicht ganz, lasse die Sicherheitskette vorgelegt und lasse mir einen Ausweis zeigen. Ich lasse niemanden ohne Termin herein und rufe bei den Stadtwerken selbst an, um nachzufragen.", explanation: "Echte Mitarbeiter melden sich vorher an und haben Verständnis für Nachfragen. Wer drängt, will oft nur in die Wohnung."),
            ExerciseItem(id: UUID(), prompt: "Eine Person ruft an, gibt sich als Mitarbeiter Ihrer Bank aus und möchte Ihre PIN wissen, um Ihr Konto zu schützen. Was antworten Sie?", options: [], correctAnswer: "Ich sage niemals meine PIN, lege auf und rufe meine Bank unter der Nummer an, die auf meiner Karte oder meinem Vertrag steht.", explanation: "Eine echte Bank fragt nie nach der PIN. Wenn Sie selbst zurückrufen, wissen Sie sicher, wer am anderen Ende ist."),
            ExerciseItem(id: UUID(), prompt: "Mitten in der Nacht piept der Rauchmelder im Flur, und Sie riechen Rauch. Was tun Sie?", options: [], correctAnswer: "Ich wecke andere Personen im Haushalt, gehe sofort ins Freie, benutze keinen Aufzug und rufe draußen die 112 an.", explanation: "Im Rauch verliert man schnell die Orientierung. Das Wichtigste ist, schnell hinauszukommen und dann die Feuerwehr zu rufen."),
            ExerciseItem(id: UUID(), prompt: "Sie sind allein im Aufzug, und er bleibt zwischen zwei Stockwerken stehen. Was tun Sie?", options: [], correctAnswer: "Ich bleibe ruhig im Aufzug, drücke den Notrufknopf und warte auf die Antwort. Wenn niemand antwortet, rufe ich mit dem Handy die 112 an. Ich versuche nicht, die Tür aufzudrücken.", explanation: "Im Aufzug ist man sicher, solange man drin bleibt. Gewaltsames Öffnen kann gefährlich werden, Hilfe ist unterwegs."),
            ExerciseItem(id: UUID(), prompt: "Aus einer Steckdose in Ihrem Wohnzimmer kommen Funken und ein Brandgeruch. Wie reagieren Sie?", options: [], correctAnswer: "Ich fasse nichts an, schalte die Sicherung im Sicherungskasten aus und lösche nicht mit Wasser. Bei Flammen oder Rauch gehe ich hinaus und rufe die 112 an.", explanation: "Wasser leitet Strom und kann zu einem Stromschlag führen. Erst den Strom abzuschalten ist der sichere Schritt."),
            ExerciseItem(id: UUID(), prompt: "Auf dem Gehweg liegt eine Person und reagiert nicht, wenn Sie sie ansprechen. Niemand ist in der Nähe. Was tun Sie zuerst?", options: [], correctAnswer: "Ich rufe sofort die 112 an, nenne den genauen Ort, sage, dass die Person nicht reagiert, und beantworte die Fragen der Leitstelle. Ich bleibe bei der Person, bis Hilfe kommt.", explanation: "Schnelle Hilfe zählt. Die Mitarbeiter der Leitstelle fragen gezielt nach und sagen Ihnen, was als Nächstes zu tun ist."),
            ExerciseItem(id: UUID(), prompt: "Sie sehen einen Verkehrsunfall, bei dem ein Auto gegen einen Baum gefahren ist. Mehrere Personen sind im Auto. Was tun Sie?", options: [], correctAnswer: "Ich halte an einer sicheren Stelle, schalte die Warnblinkanlage ein und rufe die 112 an. Ich nenne den Ort und sage, wie viele Personen betroffen sind. Ich achte darauf, selbst nicht in Gefahr zu geraten.", explanation: "Die Leitstelle schickt Rettungsdienst und bei Bedarf Polizei und Feuerwehr. Ihre eigene Sicherheit am Straßenrand geht vor."),
            ExerciseItem(id: UUID(), prompt: "Nachts hören Sie ein Geräusch im Wohnzimmer und vermuten, dass jemand eingebrochen ist. Was tun Sie?", options: [], correctAnswer: "Ich gehe nicht nachsehen, sondern bleibe im Schlafzimmer oder verlasse leise die Wohnung, schließe wenn möglich die Tür ab und rufe die 110 an.", explanation: "Die Polizei erreichen Sie unter 110. Eine Begegnung mit Einbrechern ist gefährlich, deshalb ist es besser, Abstand zu halten."),
            ExerciseItem(id: UUID(), prompt: "Im Badezimmer ist ein Wasserrohr geplatzt, und Wasser spritzt in die Wohnung. Was ist der wichtigste erste Schritt?", options: [], correctAnswer: "Ich drehe den Hauptabsperrhahn für das Wasser zu. Elektrische Geräte im nassen Bereich fasse ich nicht an. Danach informiere ich die Hausverwaltung oder den Vermieter.", explanation: "Ohne Wasserzufuhr kann der Schaden nicht größer werden. Nasse Stellen und Strom vertragen sich nicht."),
            ExerciseItem(id: UUID(), prompt: "Sie sind in einer fremden Stadt unterwegs und wissen plötzlich nicht mehr, wo Sie sind. Ihr Handy hat noch Akku. Was tun Sie?", options: [], correctAnswer: "Ich bleibe ruhig an einem belebten, hellen Ort stehen, rufe eine vertraute Person an und nenne ihr, was ich sehe, zum Beispiel einen Straßennamen. Oder ich frage in einem Geschäft nach dem Weg.", explanation: "Ziellos weiterzugehen macht es schwieriger, Sie zu finden. Ein Anruf bei einer vertrauten Person beruhigt und hilft bei der Orientierung."),
            ExerciseItem(id: UUID(), prompt: "Auf der Straße reißt Ihnen jemand die Handtasche aus der Hand und rennt weg. Was tun Sie?", options: [], correctAnswer: "Ich laufe nicht hinterher, sondern suche Hilfe bei Passanten. Ich rufe die 110 an, beschreibe die Person und die Richtung. Danach lasse ich meine Bankkarten sperren.", explanation: "Ihre Sicherheit ist wichtiger als die Tasche. Mit einer schnellen Beschreibung kann die Polizei besser suchen, und gesperrte Karten schützen Ihr Geld."),
            ExerciseItem(id: UUID(), prompt: "In der Pfanne mit heißem Öl schlagen plötzlich Flammen hoch. Was tun Sie?", options: [], correctAnswer: "Ich lösche nie mit Wasser. Ich schalte den Herd aus und lege wenn möglich einen Deckel auf die Pfanne. Wenn das Feuer nicht sofort aus ist, gehe ich hinaus und rufe die 112 an.", explanation: "Wasser auf brennendem Fett verursacht eine Stichflamme. Ein Deckel nimmt dem Feuer die Luft."),
            ExerciseItem(id: UUID(), prompt: "Bei Frost liegt vor Ihrer Haustür eine glatte Eisfläche. Sie müssen zum Arzt. Wie gehen Sie vor?", options: [], correctAnswer: "Ich streue Sand oder Splitt, wenn ich welchen habe, und gehe langsam mit kleinen Schritten und festen Schuhen. Ich halte mich am Geländer fest oder bitte jemanden um Hilfe.", explanation: "Kleine Schritte und gutes Schuhwerk verringern das Sturzrisiko. Streugut sorgt für Halt."),
            ExerciseItem(id: UUID(), prompt: "Sie sind beim Spaziergang im Freien, und ein Gewitter zieht schnell auf. Was tun Sie?", options: [], correctAnswer: "Ich suche Schutz in einem Gebäude oder in einem geschlossenen Auto. Ich stelle mich nicht unter einen einzelnen Baum und gehe nicht über freie Flächen.", explanation: "Ein einzelner hoher Baum zieht Blitze an. In einem Gebäude oder geschlossenen Auto sind Sie am besten geschützt."),
            ExerciseItem(id: UUID(), prompt: "Der Kohlenmonoxid-Warnmelder in Ihrer Wohnung schlägt Alarm, obwohl Sie nichts riechen. Was tun Sie?", options: [], correctAnswer: "Ich öffne die Fenster, gehe sofort an die frische Luft, nehme alle im Haushalt mit und rufe von draußen die 112 an. Ich gehe nicht zurück, bis die Feuerwehr es erlaubt.", explanation: "Kohlenmonoxid ist geruchlos, man kann es nicht wahrnehmen. Deshalb vertraut man dem Warnmelder und verlässt den Raum."),
            ExerciseItem(id: UUID(), prompt: "Im Hausflur spricht Sie eine fremde Person aggressiv an und kommt Ihnen immer näher. Sie fühlen sich bedroht. Was tun Sie?", options: [], correctAnswer: "Ich halte Abstand, gehe an einen belebten Ort oder zu einer Tür, hinter der jemand ist, und rufe laut um Hilfe. Wenn die Person nicht aufhört, rufe ich die 110 an.", explanation: "Hilfe zu rufen und Abstand zu halten ist kein Zeichen von Schwäche. Viele Menschen in der Nähe sind ein guter Schutz."),
            ExerciseItem(id: UUID(), prompt: "Aus der Nachbarwohnung hören Sie laute Hilferufe, aber die Tür ist verschlossen, und niemand öffnet. Was tun Sie?", options: [], correctAnswer: "Ich klopfe und rufe, ob alles in Ordnung ist. Wenn niemand öffnet oder die Hilferufe weitergehen, rufe ich die 112 an und nenne die Adresse. Ich breche die Tür nicht selbst auf.", explanation: "Der Rettungsdienst hat das nötige Werkzeug und weiß, wie er Türen sicher öffnet. Ihre Aufgabe ist es, schnell Hilfe zu holen."),
            ExerciseItem(id: UUID(), prompt: "Nach langem Regen steigt der Fluss, und im Radio wird vor Hochwasser gewarnt. Ihre Straße liegt nahe am Ufer. Was tun Sie?", options: [], correctAnswer: "Ich höre auf die Warnmeldungen, bringe wichtige Papiere in ein höheres Stockwerk und gehe nicht in den Keller. Bei Lebensgefahr oder wenn ich Hilfe brauche, rufe ich die 112 an.", explanation: "Keller können sich sehr schnell mit Wasser füllen. Warnmeldungen sagen, ob Sie das Gebiet verlassen sollen."),
            ExerciseItem(id: UUID(), prompt: "Ihr siebenjähriger Enkel ist im Park nur kurz weggelaufen und nicht mehr zu sehen. Sie suchen ihn schon einige Minuten. Was tun Sie?", options: [], correctAnswer: "Ich suche nicht lange allein weiter, sondern bitte andere Besucher um Hilfe und rufe die 110 an. Ich nenne den Namen, das Alter, die Kleidung und den Ort, an dem ich ihn zuletzt gesehen habe.", explanation: "Je früher die Polizei Bescheid weiß, desto schneller kann sie suchen. Eine genaue Beschreibung hilft dabei."),
            ExerciseItem(id: UUID(), prompt: "Jemand ruft an und sagt: „Hallo Oma, ich hatte einen Unfall und brauche sofort Geld.“ Die Stimme klingt fremd. Was tun Sie?", options: [], correctAnswer: "Ich lege auf, rufe meinen Enkel unter der Nummer an, die ich kenne, und gebe niemandem Geld oder Wertsachen an der Tür. Bei Verdacht auf Betrug rufe ich die 110 an.", explanation: "Betrüger setzen unter Zeitdruck. Ein Rückruf bei der bekannten Nummer klärt schnell, ob es wirklich Ihr Enkel ist."),
            ExerciseItem(id: UUID(), prompt: "Nachts fällt im Treppenhaus das Licht aus, und Sie müssen noch nach unten. Was tun Sie?", options: [], correctAnswer: "Ich nehme eine Taschenlampe oder das Handylicht, halte mich am Geländer fest und gehe Stufe für Stufe. Wenn ich unsicher bin, bitte ich jemanden um Hilfe.", explanation: "Die meisten Stürze passieren auf Treppen und bei schlechter Sicht. Ein Geländer und Licht geben Sicherheit."),
            ExerciseItem(id: UUID(), prompt: "Sie wollen das Haus verlassen, und auf dem Adventskranz brennen noch die Kerzen. Was tun Sie?", options: [], correctAnswer: "Ich lösche alle Kerzen, bevor ich gehe, und lasse nie eine Flamme unbeaufsichtigt brennen.", explanation: "Trockene Zweige fangen schnell Feuer. Eine Kerze ohne Aufsicht ist eine häufige Ursache für Wohnungsbrände."),
            ExerciseItem(id: UUID(), prompt: "Auf dem Gehweg kommt Ihnen ein großer Hund ohne Leine entgegen, knurrt und zeigt die Zähne. Was tun Sie?", options: [], correctAnswer: "Ich bleibe ruhig stehen, laufe nicht weg und schaue dem Hund nicht in die Augen. Ich gehe langsam rückwärts und halte Abstand, bis sein Besitzer kommt.", explanation: "Wer rennt, löst bei einem Hund leicht den Jagdtrieb aus. Ruhe und Abstand wirken beruhigend.")
        ]
    )

