            ExerciseItem(id: UUID(), prompt: "Äpfel bei Obst und Gemüse: Welches Angebot ist pro Kilogramm günstiger?\nAngebot A: 1,5 kg für 3,60 €\nAngebot B: 2 kg für 5,00 €", options: ["Angebot A — 1,5 kg für 3,60 €", "Angebot B — 2 kg für 5,00 €"], correctAnswer: "Angebot A — 1,5 kg für 3,60 €", explanation: "A kostet 3,60 € geteilt durch 1,5 gleich 2,40 € pro kg. B kostet 5,00 € geteilt durch 2 gleich 2,50 € pro kg. A ist günstiger."),
            ExerciseItem(id: UUID(), prompt: "Eier: Welches Angebot ist pro Ei günstiger?\nAngebot A: 10 Eier für 2,50 €\nAngebot B: 6 Eier für 1,62 €", options: ["Angebot A — 10 Eier für 2,50 €", "Angebot B — 6 Eier für 1,62 €"], correctAnswer: "Angebot A — 10 Eier für 2,50 €", explanation: "A kostet 2,50 € geteilt durch 10 gleich 0,25 € pro Ei. B kostet 1,62 € geteilt durch 6 gleich 0,27 € pro Ei. A ist günstiger."),
            ExerciseItem(id: UUID(), prompt: "Mineralwasser: Welches Angebot ist pro Liter günstiger?\nAngebot A: 6 Flaschen zu je 1,5 l für 4,50 €\nAngebot B: 12 Flaschen zu je 0,5 l für 3,60 €", options: ["Angebot A — 6 Flaschen zu je 1,5 l für 4,50 €", "Angebot B — 12 Flaschen zu je 0,5 l für 3,60 €"], correctAnswer: "Angebot A — 6 Flaschen zu je 1,5 l für 4,50 €", explanation: "A enthält 9 l, also 4,50 € geteilt durch 9 gleich 0,50 € pro Liter. B enthält 6 l, also 3,60 € geteilt durch 6 gleich 0,60 € pro Liter. A ist günstiger."),
            ExerciseItem(id: UUID(), prompt: "Toilettenpapier in der Drogerie: Welches Angebot ist pro Rolle günstiger?\nAngebot A: 8 Rollen für 2,40 €\nAngebot B: 16 Rollen für 4,64 €", options: ["Angebot A — 8 Rollen für 2,40 €", "Angebot B — 16 Rollen für 4,64 €"], correctAnswer: "Angebot B — 16 Rollen für 4,64 €", explanation: "A kostet 2,40 € geteilt durch 8 gleich 0,30 € pro Rolle. B kostet 4,64 € geteilt durch 16 gleich 0,29 € pro Rolle. B ist günstiger."),
