    private static let functionalWriting = Exercise(
        title: "Praktisch schreiben",
        instructions: "Schreiben Sie den kurzen Text, den die Situation verlangt.",
        section: .functionalSkills,
        type: .openEnded,
        trackedType: nil,
        difficulty: .medium,
        groupKey: "functionalWriting",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "Sie sind morgen nicht zu Hause und erwarten ein Paket. Schreiben Sie eine kurze Notiz an Ihre Nachbarin, Frau Becker, und bitten Sie sie, das Paket anzunehmen.", options: [], correctAnswer: "Liebe Frau Becker,\nich bin morgen den ganzen Tag nicht zu Hause. Könnten Sie bitte ein Paket für mich annehmen? Ich hole es abends bei Ihnen ab.\nVielen Dank und viele Grüße\nHans Weber", explanation: "Die Notiz hat eine Anrede, eine klare Bitte, einen Grund und einen Gruß. Mit „Könnten Sie bitte“ klingt die Bitte höflich."),
            ExerciseItem(id: UUID(), prompt: "Füllen Sie die Zeile „Anschrift“ in einem Formular aus. Sie heißen Anna Schmidt und wohnen in der Musterstraße 12 in 10115 Berlin.", options: [], correctAnswer: "Anna Schmidt, Musterstraße 12, 10115 Berlin", explanation: "In Deutschland steht zuerst die Straße mit der Hausnummer, dann die fünfstellige Postleitzahl und der Ort."),
            ExerciseItem(id: UUID(), prompt: "Sie können Ihren Termin in der Arztpraxis am Dienstag um 10:30 Uhr nicht wahrnehmen. Schreiben Sie eine kurze Nachricht an die Praxis.", options: [], correctAnswer: "Guten Tag,\nich kann meinen Termin am Dienstag um 10:30 Uhr leider nicht wahrnehmen. Bitte geben Sie mir einen neuen Termin.\nMit freundlichen Grüßen\nHans Weber", explanation: "Die Nachricht nennt Wochentag und Uhrzeit des Termins, damit die Praxis ihn findet. Ein Gruß und der Name am Ende machen sie vollständig."),
            ExerciseItem(id: UUID(), prompt: "Schreiben Sie einen kurzen Einkaufszettel für ein Frühstück mit mindestens vier Dingen aus verschiedenen Abteilungen des Supermarkts.", options: [], correctAnswer: "Einkaufszettel\nBackwaren: 4 Brötchen\nMolkereiprodukte: Butter, 1 l Milch\nObst und Gemüse: 500 g Erdbeeren\nGetränke: Orangensaft", explanation: "Ein Zettel nach Abteilungen geordnet spart Zeit im Laden. Mengen wie „1 l“ oder „500 g“ verhindern Fehlkäufe."),
            ExerciseItem(id: UUID(), prompt: "Sie gehen kurz zum Bäcker. Schreiben Sie eine Notiz für Ihre Familie, wohin Sie gehen und wann Sie zurück sind.", options: [], correctAnswer: "Bin beim Bäcker und gehe danach zur Apotheke. Ich bin um 15:00 Uhr wieder da.\nBis gleich!", explanation: "Eine gute Notiz sagt, wo Sie sind und wann Sie zurückkommen. Die Uhrzeit wird in Deutschland im 24-Stunden-Format mit „Uhr“ geschrieben."),
            ExerciseItem(id: UUID(), prompt: "In Ihrem Bad tropft ein Wasserhahn. Schreiben Sie eine kurze Nachricht an Ihren Vermieter, Herrn Krause.", options: [], correctAnswer: "Sehr geehrter Herr Krause,\nder Wasserhahn im Badezimmer meiner Wohnung in der Musterstraße 12 tropft seit einigen Tagen. Könnten Sie bitte jemanden vorbeischicken, der ihn repariert?\nMit freundlichen Grüßen\nAnna Schmidt", explanation: "Gegenüber einem Vermieter ist die formelle Anrede üblich. Die Nachricht nennt das Problem, den Ort und die gewünschte Hilfe."),
            ExerciseItem(id: UUID(), prompt: "Ihr Enkel Jonas hat heute Geburtstag. Schreiben Sie ihm zwei Sätze für eine Karte.", options: [], correctAnswer: "Lieber Jonas,\nzum Geburtstag wünsche ich dir alles Liebe und viel Freude. Ich freue mich schon auf unser nächstes Wiedersehen!\nAlles Liebe und bis bald!", explanation: "In einer Karte an die Familie ist die persönliche Anrede mit „du“ üblich. Ein warmer Wunsch und ein Gruß machen die Karte schön."),
            ExerciseItem(id: UUID(), prompt: "Ein Formular fragt nach Ihrer Telefonnummer. Tragen Sie eine Nummer mit der Vorwahl von Berlin ein, die Nummer lautet 1234567.", options: [], correctAnswer: "030 1234567", explanation: "Die Vorwahl von Berlin ist 030. Sie wird durch ein Leerzeichen von der übrigen Nummer getrennt."),
            ExerciseItem(id: UUID(), prompt: "Sie möchten ein Medikament in der Apotheke abholen. Schreiben Sie eine kurze Nachricht an die Apotheke.", options: [], correctAnswer: "Guten Tag,\nich möchte mein Medikament am Donnerstag nach 14:00 Uhr bei Ihnen abholen. Bitte halten Sie es bereit. Mein Rezept und meine Gesundheitskarte bringe ich mit.\nMit freundlichen Grüßen\nHans Weber", explanation: "Die Nachricht nennt Tag, Zeit und Anliegen. Die Gesundheitskarte wird in der Apotheke oft verlangt, deshalb ist der Hinweis nützlich."),
            ExerciseItem(id: UUID(), prompt: "Laden Sie eine Freundin zum Kaffee ein. Schreiben Sie ihr eine kurze Nachricht mit Tag, Uhrzeit und Adresse.", options: [], correctAnswer: "Liebe Marta,\nhast du am Samstag um 15:00 Uhr Zeit für einen Kaffee? Ich freue mich, wenn du zu mir kommst: Musterstraße 12, 10115 Berlin. Ich backe auch einen Kuchen.\nHerzliche Grüße\nAnna", explanation: "Eine Einladung braucht Tag, Uhrzeit und Ort. Die Adresse steht in der üblichen Reihenfolge: Straße mit Hausnummer, dann Postleitzahl und Ort.")
        ]
    )

    private static let cookingSteps = Exercise(
        title: "Einfache Rezepte in der richtigen Reihenfolge",
        instructions: "Bringen Sie die Schritte in die richtige Reihenfolge.",
        section: .functionalSkills,
        type: .sequencing,
        trackedType: .sequencing,
        difficulty: .medium,
        groupKey: "cookingSteps",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "Sie kochen Nudeln. Wie ist die richtige Reihenfolge?", options: ["Nudeln abgießen", "Nudeln ins kochende Wasser geben", "Topf mit Wasser füllen", "Nudeln nach Packungsangabe kochen", "Wasser zum Kochen bringen"], correctAnswer: "Topf mit Wasser füllen | Wasser zum Kochen bringen | Nudeln ins kochende Wasser geben | Nudeln nach Packungsangabe kochen | Nudeln abgießen", explanation: "Die Nudeln kommen erst ins kochende Wasser, sonst kleben sie zusammen. Abgegossen wird erst, wenn die Kochzeit vorbei ist."),
            ExerciseItem(id: UUID(), prompt: "Sie machen Rührei. Wie ist die richtige Reihenfolge?", options: ["Rührei auf den Teller geben", "Eier in die heiße Pfanne gießen", "Eier rühren, bis sie stocken", "Butter in der Pfanne erhitzen"], correctAnswer: "Butter in der Pfanne erhitzen | Eier in die heiße Pfanne gießen | Eier rühren, bis sie stocken | Rührei auf den Teller geben", explanation: "Die Pfanne muss heiß sein, bevor die Eier hineinkommen. Gerührt wird, bis sie fest geworden sind, und zum Schluss wird serviert."),
            ExerciseItem(id: UUID(), prompt: "Sie kochen Pellkartoffeln. Wie ist die richtige Reihenfolge?", options: ["Kartoffeln mit Butter servieren", "Kartoffeln waschen", "Wasser abgießen", "Kartoffeln mit Wasser bedeckt kochen", "Kartoffeln in den Topf legen"], correctAnswer: "Kartoffeln waschen | Kartoffeln in den Topf legen | Kartoffeln mit Wasser bedeckt kochen | Wasser abgießen | Kartoffeln mit Butter servieren", explanation: "Die Kartoffeln werden gewaschen, weil sie mit Schale gekocht werden. Das Wasser wird erst abgegossen, wenn sie gar sind."),
            ExerciseItem(id: UUID(), prompt: "Sie bereiten einen Tee zu. Wie ist die richtige Reihenfolge?", options: ["Teebeutel herausnehmen", "Einige Minuten ziehen lassen", "Wasser im Wasserkocher erhitzen", "Heißes Wasser über den Teebeutel in die Tasse gießen"], correctAnswer: "Wasser im Wasserkocher erhitzen | Heißes Wasser über den Teebeutel in die Tasse gießen | Einige Minuten ziehen lassen | Teebeutel herausnehmen", explanation: "Der Tee braucht heißes Wasser und Zeit zum Ziehen. Danach nimmt man den Beutel heraus, sonst wird der Tee zu bitter."),
            ExerciseItem(id: UUID(), prompt: "Sie belegen ein Butterbrot mit Käse. Wie ist die richtige Reihenfolge?", options: ["Brot essen", "Käse auf die Butter legen", "Brot aufschneiden", "Brot mit Butter bestreichen"], correctAnswer: "Brot aufschneiden | Brot mit Butter bestreichen | Käse auf die Butter legen | Brot essen", explanation: "Erst wird das Brot vorbereitet, dann wird belegt. Die Butter kommt zuerst, damit der Käse darauf hält."),
            ExerciseItem(id: UUID(), prompt: "Sie backen Pfannkuchen. Wie ist die richtige Reihenfolge?", options: ["Pfannkuchen auf einen Teller legen", "Pfannkuchen wenden", "Mehl, Milch und Eier zu einem Teig verrühren", "Teig in die heiße Pfanne gießen"], correctAnswer: "Mehl, Milch und Eier zu einem Teig verrühren | Teig in die heiße Pfanne gießen | Pfannkuchen wenden | Pfannkuchen auf einen Teller legen", explanation: "Der Teig muss fertig sein, bevor er in die heiße Pfanne kommt. Gewendet wird, wenn die Unterseite goldbraun ist."),
            ExerciseItem(id: UUID(), prompt: "Sie machen einen Gurkensalat. Wie ist die richtige Reihenfolge?", options: ["Salat mit Essig und Öl anmachen", "Gurke waschen", "Gurke in dünne Scheiben schneiden", "Gurkenscheiben in eine Schüssel geben", "Salat servieren"], correctAnswer: "Gurke waschen | Gurke in dünne Scheiben schneiden | Gurkenscheiben in eine Schüssel geben | Salat mit Essig und Öl anmachen | Salat servieren", explanation: "Gemüse wird gewaschen, bevor man es schneidet. Die Soße kommt zuletzt, damit der Salat nicht matschig wird."),
            ExerciseItem(id: UUID(), prompt: "Sie kochen einen Haferbrei. Wie ist die richtige Reihenfolge?", options: ["Brei in eine Schale füllen", "Milch zum Kochen bringen", "Haferflocken in die kochende Milch einrühren", "Unter Rühren kurz köcheln lassen", "Mit Obst garnieren"], correctAnswer: "Milch zum Kochen bringen | Haferflocken in die kochende Milch einrühren | Unter Rühren kurz köcheln lassen | Brei in eine Schale füllen | Mit Obst garnieren", explanation: "Die Flocken quellen erst in der kochenden Milch auf. Das Obst kommt erst zum Schluss obenauf."),
            ExerciseItem(id: UUID(), prompt: "Sie kochen Spaghetti mit Tomatensoße. Wie ist die richtige Reihenfolge?", options: ["Spaghetti abgießen", "Wasser zum Kochen bringen", "Spaghetti mit Tomatensoße auf Tellern anrichten", "Spaghetti ins kochende Wasser geben"], correctAnswer: "Wasser zum Kochen bringen | Spaghetti ins kochende Wasser geben | Spaghetti abgießen | Spaghetti mit Tomatensoße auf Tellern anrichten", explanation: "Die Spaghetti garen erst im kochenden Wasser und werden danach abgegossen. Zum Schluss werden sie mit der Soße auf Tellern angerichtet."),
            ExerciseItem(id: UUID(), prompt: "Sie wollen einen Kuchen aus dem Backofen nehmen. Wie ist die richtige Reihenfolge?", options: ["Kuchen abkühlen lassen", "Kuchen auf ein Gitter stellen", "Kuchen aus dem Ofen holen", "Ofenhandschuhe anziehen"], correctAnswer: "Ofenhandschuhe anziehen | Kuchen aus dem Ofen holen | Kuchen auf ein Gitter stellen | Kuchen abkühlen lassen", explanation: "Man schützt zuerst die Hände, bevor man etwas Heißes herausnimmt. Danach kühlt der Kuchen auf einem Gitter ab.")
        ]
    )

    private static let dailyLifeSkills = Exercise(
        title: "Alltag meistern",
        instructions: "Beantworten Sie die Frage in einem oder zwei Sätzen.",
        section: .functionalSkills,
        type: .openEnded,
        trackedType: nil,
        difficulty: .medium,
        groupKey: "dailyLifeSkills",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "Wie schicken Sie einen Brief an eine Freundin ab?", options: [], correctAnswer: "Ich schreibe die Adresse auf den Umschlag, klebe eine Briefmarke in die rechte obere Ecke und werfe den Brief in einen Briefkasten.", explanation: "Ohne Briefmarke wird der Brief nicht befördert. Auf dem Briefkasten steht, wann er geleert wird."),
            ExerciseItem(id: UUID(), prompt: "In Ihrem Briefkasten liegt eine Benachrichtigungskarte der Post. Wie holen Sie das Paket ab?", options: [], correctAnswer: "Ich gehe mit der Karte und meinem Ausweis zur genannten Postfiliale oder Abholstelle und nenne dort meinen Namen.", explanation: "Auf der Karte steht, wo das Paket liegt. Der Ausweis zeigt, dass es Ihnen gehört."),
            ExerciseItem(id: UUID(), prompt: "Wie heben Sie mit Ihrer Girocard Geld am Automaten ab?", options: [], correctAnswer: "Ich stecke die Karte in den Automaten, gebe meine PIN ein und halte die Hand dabei über die Tasten. Dann wähle ich den Betrag und nehme Karte und Geld wieder mit.", explanation: "Wenn Sie die Tasten verdecken, kann niemand die PIN sehen. Vergessen Sie nicht, die Karte mitzunehmen."),
            ExerciseItem(id: UUID(), prompt: "Wie kaufen Sie am Automaten eine Fahrkarte für den Bus oder die Bahn?", options: [], correctAnswer: "Ich wähle das Ziel oder die Zone und die Art der Fahrkarte, zum Beispiel Einzelfahrt. Dann bezahle ich und nehme die Fahrkarte und das Rückgeld mit.", explanation: "Wählen Sie das Ziel zuerst, damit der Automat den richtigen Preis anzeigt. Entwerten Sie die Karte, wenn es erforderlich ist."),
            ExerciseItem(id: UUID(), prompt: "Wie vereinbaren Sie telefonisch einen Termin in einer Arztpraxis?", options: [], correctAnswer: "Ich sage meinen Namen und mein Anliegen und frage nach einem freien Termin. Ich schreibe Tag und Uhrzeit auf und wiederhole sie zur Kontrolle.", explanation: "Ein Zettel neben dem Telefon hilft. Wenn Sie den Termin wiederholen, vermeiden Sie Missverständnisse."),
            ExerciseItem(id: UUID(), prompt: "Sie können einen Termin nicht einhalten. Wie sagen Sie ihn ab?", options: [], correctAnswer: "Ich rufe so früh wie möglich an, nenne meinen Namen und den Termin und sage, dass ich nicht kommen kann. Wenn möglich, frage ich nach einem neuen Termin.", explanation: "Wer früh absagt, gibt anderen die Chance, den Termin zu bekommen. Das ist höflich und praktisch."),
            ExerciseItem(id: UUID(), prompt: "Ihre Bankkarte ist weg. Was tun Sie als Erstes?", options: [], correctAnswer: "Ich rufe sofort meine Bank an und lasse die Karte sperren. Danach prüfe ich meine Kontoumsätze.", explanation: "Eine schnelle Sperrung schützt vor Missbrauch. Die Telefonnummer steht meist auf der Bank-Website oder im Vertrag."),
            ExerciseItem(id: UUID(), prompt: "Wie teilen Sie dem Busfahrer mit, dass Sie an der nächsten Haltestelle aussteigen möchten?", options: [], correctAnswer: "Ich drücke rechtzeitig vor der Haltestelle den Halteknopf und gehe zur Tür. Ich steige erst aus, wenn der Bus steht.", explanation: "Der Knopf zeigt dem Fahrer, dass jemand aussteigen möchte. Im fahrenden Bus bleibt man sicher sitzen oder hält sich fest."),
            ExerciseItem(id: UUID(), prompt: "Wie lösen Sie ein Rezept in der Apotheke ein?", options: [], correctAnswer: "Ich gebe der Apothekerin oder dem Apotheker mein Rezept und meine Gesundheitskarte. Ich warte auf das Medikament und frage bei Unklarheiten nach.", explanation: "Die Gesundheitskarte gehört meist dazu. Das Fachpersonal beantwortet gerne Ihre Fragen."),
            ExerciseItem(id: UUID(), prompt: "Wie trennen Sie Ihren Müll zu Hause?", options: [], correctAnswer: "Papier kommt in die Papiertonne, Verpackungen aus Plastik oder Metall in den gelben Sack, Essensreste in die Biotonne und der Rest in die Restmülltonne.", explanation: "Gute Mülltrennung hilft beim Recycling. Die Regeln können sich je nach Stadt etwas unterscheiden."),
            ExerciseItem(id: UUID(), prompt: "Wie geben Sie leere Pfandflaschen im Supermarkt zurück?", options: [], correctAnswer: "Ich bringe die Flaschen zum Pfandautomaten, stecke sie einzeln hinein und drücke am Ende die Taste für den Pfandbon. Den Bon gebe ich an der Kasse ab.", explanation: "Der Bon wird beim Einkauf verrechnet. So bekommen Sie das Pfand zurück."),
            ExerciseItem(id: UUID(), prompt: "Sie haben sich in der Stadt verlaufen. Wie fragen Sie höflich nach dem Weg zum Bahnhof?", options: [], correctAnswer: "Ich sage: „Entschuldigung, können Sie mir bitte sagen, wie ich zum Bahnhof komme?“ Danach bedanke ich mich.", explanation: "„Entschuldigung“ und „bitte“ machen die Frage höflich. Wenn Sie die Antwort wiederholen, merken Sie, ob Sie alles verstanden haben."),
            ExerciseItem(id: UUID(), prompt: "Wie bestellen Sie beim Bäcker drei Brötchen und ein Brot?", options: [], correctAnswer: "Ich sage: „Guten Tag, ich hätte gern drei Brötchen und ein Brot, bitte.“ Danach bezahle ich und bedanke mich.", explanation: "Mit „ich hätte gern“ klingt die Bestellung höflich. Zählen Sie die Mengen deutlich."),
            ExerciseItem(id: UUID(), prompt: "Wie stellen Sie auf Ihrem Handy einen Wecker für 7:00 Uhr?", options: [], correctAnswer: "Ich öffne die Uhr-App, wähle „Wecker“ und tippe auf das Plus. Dann stelle ich 7:00 Uhr ein und speichere.", explanation: "Prüfen Sie nach dem Speichern, ob der Wecker eingeschaltet ist. Dann klingelt er jeden eingestellten Tag."),
            ExerciseItem(id: UUID(), prompt: "Wie machen Sie telefonisch einen Termin beim Friseur aus?", options: [], correctAnswer: "Ich sage meinen Namen, nenne die gewünschte Leistung, zum Beispiel Haare schneiden, und frage nach einem Tag und einer Uhrzeit. Ich schreibe den Termin auf.", explanation: "Wenn Sie sagen, was Sie möchten, kann der Friseur die Zeit richtig planen."),
            ExerciseItem(id: UUID(), prompt: "Wie beschriften Sie einen Briefumschlag für einen Brief an Anna Schmidt, Musterstraße 12, 10115 Berlin?", options: [], correctAnswer: "In die Mitte schreibe ich in drei Zeilen: Anna Schmidt / Musterstraße 12 / 10115 Berlin. Meinen Absender schreibe ich klein auf die Rückseite oder oben links.", explanation: "Die Postleitzahl steht vor dem Ort. Der Absender hilft, wenn der Brief nicht zugestellt werden kann."),
            ExerciseItem(id: UUID(), prompt: "Wie lesen Sie am Aushang die Abfahrtszeit Ihres Busses ab?", options: [], correctAnswer: "Ich suche die Linie und die Haltestelle, schaue in die Spalte für den richtigen Wochentag und suche die nächste Abfahrt nach der aktuellen Uhrzeit.", explanation: "Wochentage und Wochenende haben oft verschiedene Fahrpläne. Die Uhrzeiten werden im 24-Stunden-Format angegeben."),
            ExerciseItem(id: UUID(), prompt: "Wie bitten Sie im Restaurant um die Rechnung?", options: [], correctAnswer: "Ich winke freundlich oder sage: „Wir möchten bitte zahlen.“ Dann nenne ich der Bedienung den Betrag, den ich geben möchte, damit sie das Trinkgeld berücksichtigt.", explanation: "In Deutschland gibt man oft etwa fünf bis zehn Prozent Trinkgeld. Es ist freiwillig und wird beim Bezahlen genannt."),
            ExerciseItem(id: UUID(), prompt: "Wie sortieren Sie Ihre Wäsche, bevor Sie die Waschmaschine einschalten?", options: [], correctAnswer: "Ich trenne helle und dunkle Wäsche und lese die Pflegeetiketten. Ich wasche nur Teile zusammen, die dieselbe Temperatur vertragen.", explanation: "Dunkle Teile können beim Waschen Farbe verlieren und helle verfärben. Die Etiketten sagen, bei wie viel °C man waschen darf."),
            ExerciseItem(id: UUID(), prompt: "Wie melden Sie sich höflich, wenn Sie bei einer Firma anrufen und jemand abhebt?", options: [], correctAnswer: "Ich sage: „Guten Tag, hier spricht Hans Weber. Ich möchte gern mit der Verkaufsabteilung sprechen.“", explanation: "Wer zuerst Gruß und Namen nennt, wird besser verstanden. Danach folgt kurz und klar das Anliegen.")
        ]
    )
}
